import {modelFollowMarkup,mountModelFollow} from './model-follows.js?v=20261009-follow-email';
import {postBody} from './post-format.js';
import {TEAM_COLORS} from './vendor/mdlxl/src/team-colors.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const bylineHtml=card=>postBody(card.byline).replace(/^<p>|<\/p>$/g,'');
export function uploadedModelCard(card,colour='#9c0000'){return `<article class="model-card slab"><a class="model-open" href="#model/${escape(card.id)}" aria-label="Open ${escape(card.name)}"><div class="card-portrait" style="--aura:${colour}"><img src="${escape(card.coverUrl)}" alt="${escape(card.name)}"></div></a><div class="card-text"><a class="card-name" href="#model/${escape(card.id)}">${escape(card.name)}</a><div class="card-author">By: ${bylineHtml(card)}</div></div></article>`;}
export async function renderUnitCard(app,card,{isCurrent,recordUsage,confirmation='',colour='#ff0303'}){
 const {createViewer}=await import('./viewer.js?v=20261009-unit-upload');
 let viewer,disposed=false,version=0;
 const owner={dispose(){disposed=true;version++;viewer?.dispose();}};
 app.innerHTML=`<div class="model-title"><div><h1>${escape(card.name)}</h1><div class="byline">By: ${bylineHtml(card)}</div></div></div><div class="model-layout"><section class="viewer slab" aria-label="Live model viewer"><div class="viewer-label"><span>MODEL SHOWCASE</span></div><div class="viewport"><div class="model-stage"><canvas id="model-canvas" aria-label="Live model. Drag to rotate, right-drag to pan, scroll to zoom."></canvas><img class="portrait-frame" src="ui/human-portrait-frame.png" alt="" aria-hidden="true"></div><div class="viewport-hint">Drag to rotate · Right-drag to pan · Scroll to zoom</div><div id="viewer-message" class="viewer-error">Loading model…</div></div><div class="controls"><div class="control-row"><label for="unit-model">Model</label><select id="unit-model">${card.models.map((m,i)=>`<option value="${i}" ${m.assetId===card.defaultModelId?'selected':''}>${escape(m.name)}</option>`).join('')}</select></div><div class="control-row animation-controls"><label for="sequence">Animation</label><select id="sequence" disabled></select><button id="play" class="iron-button" disabled>Pause</button></div><div class="control-row appearance-controls"><label for="team">Team colour</label><select id="team">${TEAM_COLORS.map(c=>`<option value="${c.rgbHex}" ${c.rgbHex===colour?'selected':''}>${escape(c.name)}</option>`).join('')}</select><button id="reset" class="iron-button" disabled>Reset view</button></div></div></section><section class="details slab"><div class="tabs" role="tablist" aria-label="Model information"><button id="tab-description" role="tab" aria-selected="true">Description</button><button id="tab-credits" role="tab" aria-selected="false">Detailed credits</button></div><div id="tab-content" class="tab-content post-body" role="tabpanel" aria-labelledby="tab-description"></div><div class="tab-footer">${card.models.length} model${card.models.length===1?'':'s'} · Warcraft III</div></section></div>`;
 const panel=app.querySelector('#tab-content'),modelSelect=app.querySelector('#unit-model'),team=app.querySelector('#team'),message=app.querySelector('#viewer-message'),sequence=app.querySelector('#sequence'),play=app.querySelector('#play'),reset=app.querySelector('#reset');
 const downloads=document.querySelector('#catalogue-summary');
 function showDownloads(model){downloads.innerHTML=`<h2>Downloads</h2><div class="side-downloads"><a class="iron-button" href="${escape(model.fileUrl)}&download=1" data-model="${card.id}" data-download="mdx" download="${escape(model.name)}">Download selected model</a>${card.downloads.filter(file=>file.id!==model.assetId).map(file=>`<a class="iron-button" href="${escape(file.url)}&download=1" data-model="${card.id}" data-download="${/\.zip$/i.test(file.name)?'pack':'mdx'}" download="${escape(file.name)}">${escape(file.name)}</a>`).join('')}</div>${modelFollowMarkup()}<p class="page-note">${escape(card.projectName)}</p>`;mountModelFollow(downloads.querySelector('.model-follow'),card,{confirmation});confirmation='';}
 function tab(credits){app.querySelector('#tab-description').setAttribute('aria-selected',String(!credits));app.querySelector('#tab-credits').setAttribute('aria-selected',String(credits));panel.setAttribute('aria-labelledby',credits?'tab-credits':'tab-description');panel.innerHTML=credits?'<h2>Credits</h2><div class="credit-intro">By: '+bylineHtml(card)+'</div>'+postBody(card.credits):'<h2>'+escape(card.name)+'</h2>'+postBody(card.description);}
 app.querySelector('#tab-description').onclick=()=>tab(false);app.querySelector('#tab-credits').onclick=()=>tab(true);tab(false);
 async function load(){
  const current=++version,model=card.models[Number(modelSelect.value)];viewer?.dispose();viewer=null;const old=app.querySelector('#model-canvas'),canvas=old.cloneNode();old.replaceWith(canvas);sequence.disabled=play.disabled=reset.disabled=true;message.hidden=false;message.textContent='Loading '+model.name+'…';showDownloads(model);
  try{const next=await createViewer(canvas,{...model,file:model.name},{teamColor:team.value,onPortraitModeChange:active=>app.querySelector('.viewport')?.classList.toggle('portrait-mode',active)});if(disposed||!isCurrent()||current!==version){next.dispose();return;}viewer=next;sequence.replaceChildren(...next.model.Sequences.map((s,i)=>new Option(s.Name,String(i),false,s.Name==='Stand'||s.Name==='Stand - 1')));message.hidden=true;sequence.disabled=play.disabled=reset.disabled=false;play.textContent='Pause';window.__modelReady=true;}catch(error){if(isCurrent()&&current===version)message.textContent='The preview could not load: '+error.message;}
 }
 modelSelect.onchange=load;sequence.onchange=()=>viewer?.sequence(Number(sequence.value));play.onclick=()=>play.textContent=viewer.pause()?'Pause':'Play';reset.onclick=()=>viewer?.reset();team.onchange=async()=>{try{await viewer?.colour(team.value);}catch(error){message.hidden=false;message.textContent=error.message;}};
 await load();return owner;
}
